                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && inventItemBarcode.BarcodeSetupId  == _barcodeSetupId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
                }
                else
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && inventItemBarcode.BarcodeSetupId  == _barcodeSetupId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                        && inventItemBarcode.inventDimId     == productInventDimId;
                }
            }
        }
        else
        {
            if (_onlyPrint && _onlyInput)
            {
                if (!isFindBarcodeByInventDimId || !productInventDimId)
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.UseForPrinting  == NoYes::Yes
                        && inventItemBarcode.UseForInput     == NoYes::Yes
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
                }
                else
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.UseForPrinting  == NoYes::Yes
                        && inventItemBarcode.UseForInput     == NoYes::Yes
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                        && inventItemBarcode.inventDimId     == productInventDimId;
                }
            }
            else if (_onlyPrint)
            {
                if (!isFindBarcodeByInventDimId || !productInventDimId)
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.UseForPrinting  == NoYes::Yes
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
                }
                else
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.UseForPrinting  == NoYes::Yes
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                        && inventItemBarcode.inventDimId     == productInventDimId;
                }
            }
            else if (_onlyInput)
            {
                if (!isFindBarcodeByInventDimId || !productInventDimId)
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.UseForInput     == NoYes::Yes
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
                }
                else
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.UseForInput     == NoYes::Yes
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                        && inventItemBarcode.inventDimId     == productInventDimId;
                }
            }
            else
            {
                if (!isFindBarcodeByInventDimId || !productInventDimId)
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                    #InventDimExistsJoin(inventItemBarcode.inventDimId, inventDim, _inventDimCriteria, inventDimParm);
                }
                else
                {
                    select firstonly inventItemBarcode
                    where inventItemBarcode.ItemId          == _itemId
                        && (!_unitId || inventItemBarcode.UnitID == _unitId)
                        && inventItemBarcode.METDefault      == NoYes::Yes
                        && inventItemBarcode.METVendAccount  == _vendAccount
                        && inventItemBarcode.inventDimId     == productInventDimId;
                }
            }
        }

        if (isTransactionScopeCacheEnabled)
        {
            SysTransactionScopeCache::set(cacheScope, cacheKey, inventItemBarcode);
        }

        return inventItemBarcode;
    }

    /// <summary>
    /// Method to fetch Barcode for Purchase order line. This custom method is almost similar to standard findPurchBarcodeDimension added with additonal parameter- Vendor account. 
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventDim">An <t>inventDim</t>buffer</param>
    /// <param name = "_barcodeSetupId">Barcode Id</param>
    /// <param name = "_unitId">Unit of measure symbol</param>
    /// <param name = "_vendAccount">Vendor account Id</param>
    /// <returns>An <t>InventItemBarcode</t> buffer</returns>
    public static InventItemBarcode metFindPurchBarcodeDimension(ItemId _itemId, InventDim _inventDim, BarcodeSetupId _barcodeSetupId = '', UnitOfMeasureSymbol _unitId = '', VendAccount _vendAccount = '')
    {
        InventItemBarcode inventItemBarcode = InventItemBarcode::metFindByProductDimensions(_itemId, _inventDim, false, true, _barcodeSetupId, _unitId, _vendAccount);

        if (!inventItemBarcode)
        {
            inventItemBarcode = InventItemBarcode::metFindByProductDimensions(_itemId, _inventDim, false, false, _barcodeSetupId, _unitId, _vendAccount);
        }

        return inventItemBarcode;
    }
